DEFAULT_TYPES = [
    ("restaurant", "Restaurant"),
    ("hotel", "Hôtel"),
    ("fish_shop", "Poissonnerie"),
    ("supermarket", "Supermarché"),
    ("wholesaler", "Grossiste"),
    ("caterer", "Traiteur"),
    ("individual", "Particulier"),
]


def seed_customer_types(apps, schema_editor):
    """Every organization gets the seven types it had as a fixed list (D-283), so no customer loses its type."""
    Organization = apps.get_model("core", "Organization")
    CustomerType = apps.get_model("partners", "CustomerType")
    Customer = apps.get_model("partners", "Customer")
    for organization in Organization.objects.all():
        codes = [code for code, _label in DEFAULT_TYPES]
        rows = [
            CustomerType(organization=organization, code=code, label=label, position=index)
            for index, (code, label) in enumerate(DEFAULT_TYPES)
        ]
        used = set(Customer.objects.filter(organization=organization).values_list("kind", flat=True))
        for extra in sorted(used - set(codes)):
            rows.append(CustomerType(organization=organization, code=extra, label=extra, position=len(rows)))
        CustomerType.objects.bulk_create(rows, ignore_conflicts=True)


